# resolution-record.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/resolution-record.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "allOf": [
    {
      "if": {
        "properties": {
          "decision": {
            "const": "approved"
          }
        }
      },
      "then": {
        "properties": {
          "successor_attempt_id": {
            "minLength": 1,
            "type": "string"
          }
        },
        "required": [
          "successor_attempt_id"
        ]
      }
    },
    {
      "if": {
        "properties": {
          "decision": {
            "enum": [
              "rejected",
              "withdrawn"
            ]
          }
        }
      },
      "then": {
        "properties": {
          "successor_attempt_id": {
            "type": "null"
          }
        }
      }
    }
  ],
  "properties": {
    "authority_ref": {
      "minLength": 1,
      "type": "string"
    },
    "decision": {
      "enum": [
        "approved",
        "rejected",
        "withdrawn"
      ]
    },
    "gate_id": {
      "minLength": 1,
      "type": "string"
    },
    "recorded_at": {
      "format": "date-time",
      "type": "string"
    },
    "request_digest": {
      "pattern": "^sha256:[A-Fa-f0-9]{64}$",
      "type": "string"
    },
    "resolution_id": {
      "minLength": 1,
      "type": "string"
    },
    "schema_version": {
      "const": 1
    },
    "send_id": {
      "minLength": 1,
      "type": "string"
    },
    "successor_attempt_id": {
      "type": [
        "string",
        "null"
      ]
    }
  },
  "required": [
    "schema_version",
    "resolution_id",
    "gate_id",
    "send_id",
    "decision",
    "authority_ref",
    "recorded_at"
  ],
  "title": "CHD ResolutionRecord v1",
  "type": "object"
}
```
